//! Graph P32: projection and lineage integrity contracts for typed research graphs.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.graph.projection-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GraphNode4{pub node_id:String,pub kind:String,pub digest:String,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct GraphEdge4{pub edge_id:String,pub source:String,pub target:String,pub relation:String,pub digest:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ProjectionRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub nodes:Vec<GraphNode4>,pub edges:Vec<GraphEdge4>,pub required_node_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub node_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ProjectionArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ProjectionCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub node_order:Vec<String>,pub edge_order:Vec<String>,pub selected_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub relation_order:Vec<String>,pub kind_order:Vec<String>,pub orphan_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:ProjectionArtifact4}
#[derive(Debug,Error)] pub enum ProjectionIntegrityError{#[error("projection integrity input is invalid: {0}")] Invalid(String),#[error("projection integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->ProjectionIntegrityError{ProjectionIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"graph","consumers":["knowledge compiler","mechanism explorer","analysis runtime","research workbench"],"behavior":format!("qualify typed graph projections at {scale} ({mode})"),"value":"prevents orphaned, cyclically unsafe, semantically untyped, or unprovenanced graph projections from driving research workflows","input_schema":"ProjectionRequest4@1","output_schema":"ProjectionCard7@1","effects":["emit:projection-card","retain:lineage-loss","block:unsafe-projection"],"permissions":["read:local-graph-fixtures"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&ProjectionCard7)->Result<(),ProjectionIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("projection identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.node_order,&c.edge_order,&c.selected_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.relation_order,&c.kind_order,&c.orphan_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("projection vectors are not canonical"));}}let ids=c.node_order.iter().collect::<BTreeSet<_>>();let states=c.selected_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("node states do not partition nodes"));}Ok(())}
pub fn qualify(q:&ProjectionRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<ProjectionCard7,ProjectionIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.nodes.is_empty()||q.required_node_order.is_empty()||!canonical(&q.required_node_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.node_budget==0{return Err(invalid("projection identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut nodes=q.nodes.clone();nodes.sort_by(|a,b|a.node_id.cmp(&b.node_id));let mut seen=BTreeSet::new();let mut selected=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut kinds=BTreeSet::new();let mut orphans=BTreeSet::new();let mut evidence=BTreeSet::new();for n in &nodes{if n.node_id.trim().is_empty()||!seen.insert(n.node_id.clone())||n.kind.trim().is_empty()||!digest(&n.digest)||n.evidence_state.trim().is_empty()||!n.local||!n.aggregate_only{return Err(invalid("node identity, kind, digest, evidence, or locality is invalid"));}kinds.insert(format!("{}:{}",n.node_id,n.kind));evidence.insert(n.digest.clone());if n.evidence_state=="unknown"||n.digest==q.replay_identity{unknown.insert(n.node_id.clone());}else if !q.required_node_order.contains(&n.node_id){omitted.insert(n.node_id.clone());}else{selected.insert(n.node_id.clone());}}let ids=seen.clone();let mut edges=BTreeSet::new();let mut relations=BTreeSet::new();for e in &q.edges{if e.edge_id.trim().is_empty()||!edges.insert(e.edge_id.clone())||e.source.trim().is_empty()||e.target.trim().is_empty()||e.source==e.target||!ids.contains(&e.source)||!ids.contains(&e.target)||e.relation.trim().is_empty()||!digest(&e.digest){return Err(invalid("edge identity, endpoint, self-loop, relation, or digest is invalid"));}relations.insert(format!("{}:{}",e.edge_id,e.relation));}for n in &ids{if !q.edges.iter().any(|e|&e.source==n||&e.target==n){orphans.insert(n.clone());}}let missing=q.required_node_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||nodes.len()>q.node_budget;if global{omitted.extend(seen.iter().cloned());selected.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !orphans.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"node_order":seen.iter().cloned().collect::<Vec<_>>()});let closure_digest=ContentHash::of_value(&body).map_err(|e|ProjectionIntegrityError::Digest(e.to_string()))?.to_string();let selected_order=selected.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let artifact=ProjectionArtifact4{artifact_id:format!("graph-projection:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:omitted_order.clone(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=ProjectionCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),node_order:body["node_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),edge_order:edges.into_iter().collect(),selected_order,rejected_order,unknown_order,omitted_order,relation_order:relations.into_iter().collect(),kind_order:kinds.into_iter().collect(),orphan_order:orphans.into_iter().collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts:if disposition=="qualified"{vec![format!("approve:projection:{}",q.request_id)]}else{vec!["block:unsafe-projection".into()]},artifact};validate_card(&c)?;let _=(scale,mode);Ok(c)}
